<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(16, 24, 42, 0.88);
        --panel-strong: #121a2d;
        --border: rgba(148, 163, 184, 0.18);
        --text: #e5eefb;
        --muted: #9aa8c7;
        --danger: #ff5d73;
        --danger-strong: #ff3b57;
        --secondary: #1d2942;
        --shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 20px;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(83, 110, 255, 0.16), transparent 35%),
          linear-gradient(180deg, #11192e 0%, var(--bg) 100%);
      }

      .page {
        width: min(100%, 920px);
      }

      .preview-card {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 28px;
        background: linear-gradient(180deg, rgba(20, 28, 49, 0.96), rgba(12, 17, 31, 0.98));
        box-shadow: var(--shadow);
      }

      .preview-image {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        background: #0f172a;
      }

      .preview-body {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 24px;
      }

      .eyebrow {
        margin: 0 0 8px;
        font-size: 0.78rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: #89a1ff;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.5rem, 2vw, 2.2rem);
      }

      .meta {
        margin: 10px 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 13px 22px;
        font: inherit;
        font-weight: 700;
        color: var(--text);
        cursor: pointer;
        transition: transform 160ms ease, opacity 160ms ease, background 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      .trigger {
        background: linear-gradient(180deg, var(--danger), var(--danger-strong));
        box-shadow: 0 12px 24px rgba(255, 59, 87, 0.28);
      }

      .status {
        margin-top: 16px;
        min-height: 1.5em;
        color: #8cf0c4;
        font-weight: 600;
      }

      dialog {
        width: min(92vw, 460px);
        padding: 0;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 24px;
        color: var(--text);
        background:
          linear-gradient(180deg, rgba(25, 34, 58, 0.98), rgba(13, 19, 35, 0.98));
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(3, 7, 18, 0.72);
        backdrop-filter: blur(8px);
      }

      .dialog-body {
        padding: 28px;
      }

      .dialog-icon {
        width: 52px;
        height: 52px;
        display: inline-grid;
        place-items: center;
        border-radius: 16px;
        font-size: 1.4rem;
        background: rgba(255, 93, 115, 0.12);
        color: #ff8fa0;
      }

      .dialog-title {
        margin: 18px 0 10px;
        font-size: 1.45rem;
      }

      .dialog-copy {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .secondary {
        background: var(--secondary);
      }

      .danger {
        background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      }

      .deleted .preview-image {
        filter: grayscale(1) brightness(0.55);
      }

      .deleted .trigger {
        opacity: 0.45;
        pointer-events: none;
      }

      @media (max-width: 700px) {
        .preview-body {
          flex-direction: column;
          align-items: stretch;
        }

        .dialog-actions {
          flex-direction: column-reverse;
        }

        .dialog-actions button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="preview-card" id="previewCard">
        <img
          class="preview-image"
          src="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 1000'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop stop-color='%231f2f58' offset='0'/><stop stop-color='%233d6cff' offset='0.55'/><stop stop-color='%238ad4ff' offset='1'/></linearGradient></defs><rect width='1600' height='1000' fill='%230b1020'/><circle cx='1250' cy='240' r='170' fill='%23ff87b5' fill-opacity='0.75'/><path d='M0 790L290 530l210 185 230-280 210 186 150-118 510 287V1000H0z' fill='url(%23g)'/><path d='M0 860l320-220 195 146 202-201 214 126 238-175 431 324V1000H0z' fill='%230d1735' fill-opacity='0.9'/><text x='120' y='150' fill='white' fill-opacity='0.9' font-family='Arial, sans-serif' font-size='54'>Northern Glow</text></svg>"
          alt="Large preview of a landscape from the image library"
        />
        <div class="preview-body">
          <div>
            <p class="eyebrow">Image preview</p>
            <h1>Northern Glow</h1>
            <p class="meta">
              Captured in Iceland · 6016 × 4016 · RAW + edited copy
            </p>
            <p class="status" id="statusMessage" aria-live="polite"></p>
          </div>
          <button type="button" class="trigger" id="openDialogButton">
            Delete image
          </button>
        </div>
      </section>
    </main>

    <dialog id="deleteDialog" aria-labelledby="dialogTitle">
      <div class="dialog-body">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <h2 class="dialog-title" id="dialogTitle">Delete this image?</h2>
        <p class="dialog-copy">
          This will remove <strong>Northern Glow</strong> from your library. You can’t
          undo this action once the image has been deleted.
        </p>
        <div class="dialog-actions">
          <button type="button" class="secondary" id="cancelButton">Cancel</button>
          <button type="button" class="danger" id="confirmDeleteButton">
            Delete from library
          </button>
        </div>
      </div>
    </dialog>

    <script>
      const previewCard = document.getElementById("previewCard");
      const statusMessage = document.getElementById("statusMessage");
      const deleteDialog = document.getElementById("deleteDialog");
      const openDialogButton = document.getElementById("openDialogButton");
      const cancelButton = document.getElementById("cancelButton");
      const confirmDeleteButton = document.getElementById("confirmDeleteButton");

      openDialogButton.addEventListener("click", () => {
        deleteDialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        deleteDialog.close();
      });

      deleteDialog.addEventListener("click", (event) => {
        const bounds = deleteDialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom;

        if (clickedOutside) {
          deleteDialog.close();
        }
      });

      confirmDeleteButton.addEventListener("click", () => {
        previewCard.classList.add("deleted");
        statusMessage.textContent = "Image deleted from your library.";
        deleteDialog.close();
      });
    </script>
  </body>
</html>
